import { join } from 'node:path';
import { promisify } from 'node:util';
import { credentials, loadPackageDefinition } from '@grpc/grpc-js';
import { loadSync } from '@grpc/proto-loader';
import { CartServiceClient, type Cart } from './gen/cart';
// Generated by grpc-tools and not committed.
import { CatalogServiceClient, ShippingServiceClient } from './gen/shop_grpc_pb';
import { LedgerServiceClient } from './gen/ledger_grpc_pb';

const { CART_ADDR = '' } = process.env;

// Generated code committed beside this file: its paths name each method.
const cart = new CartServiceClient(CART_ADDR, credentials.createInsecure());
const addItemAsync = promisify(cart.addItem).bind(cart);

// The contract loaded at run time.
const shop = loadPackageDefinition(loadSync(join(__dirname, '../../proto/shop.proto'))) as any;
const payments = new shop.shop.PaymentService(process.env.PAYMENTS_ADDR, credentials.createInsecure());

// Generated code nobody committed: the contract says what each is.
const catalog = new CatalogServiceClient('catalog:50051', credentials.createInsecure());
const shipping = new ShippingServiceClient(process.env.SHIPPING_ADDR, credentials.createInsecure());
// No contract here declares this one.
const ledger = new LedgerServiceClient(process.env.LEDGER_ADDR, credentials.createInsecure());

export function getCart(userId: string): Promise<Cart> {
  return new Promise((resolve, reject) => cart.getCart({ userId }, (error, reply) => (error ? reject(error) : resolve(reply))));
}

export async function addToCart(userId: string, productId: string): Promise<void> {
  await addItemAsync({ userId, productId, quantity: 1 });
}

export function checkout(userId: string, amount: number): Promise<unknown> {
  return new Promise((resolve, reject) => {
    payments.charge({ orderId: userId, amount }, (error: Error | null, reply: unknown) => (error ? reject(error) : resolve(reply)));
    cart.emptyCart({ userId }, () => undefined);
  });
}

export function listProducts(): Promise<unknown> {
  return new Promise((resolve) => catalog.listProducts({}, (_error: unknown, reply: unknown) => resolve(reply)));
}

export function quote(zip: string): Promise<unknown> {
  return new Promise((resolve) => shipping.getQuote({ zip }, (_error: unknown, reply: unknown) => resolve(reply)));
}

export function record(entry: string): void {
  ledger.append({ entry }, () => undefined);
}

export function shutdown(): void {
  cart.close();
}
